const DELETE = ["gearSource_colete_couro","gearSource_couraca_rebitada","gearSource_luvas_precisao","gearSource_botas_explorador","gearSource_oculos_engenheiro","gearSource_couro_reforcado","gearSource_injetor_vapor","gearSource_vigilia_elmo","gearSource_vigilia_peitoral","gearSource_vigilia_luvas","gearSource_vigilia_botas","gearSource_forja_elmo","gearSource_forja_peitoral","gearSource_forja_luvas","gearSource_forja_botas","gearSource_sentinela_elmo","gearSource_sentinela_peitoral","gearSource_sentinela_luvas","gearSource_sentinela_botas","gearUses_couro_reforcado","gearUses_injetor_vapor"]

for (const [lang, i] of [["pt-BR", 1], ["en", 2], ["es", 3]]) {
  const file = path.join(DIR, lang + ".json")
  const dict = JSON.parse(fs.readFileSync(file, "utf8"))
  const mm = dict.MeuMundo
  if (!mm) throw new Error("sem MeuMundo em " + lang)
  let a = 0, o = 0, d = 0
  for (const row of UI) if (!(row[0] in mm)) { mm[row[0]] = row[i]; a++ }
  for (const row of ITEMS) if (mm[row[0]] !== row[i]) { mm[row[0]] = row[i]; o++ }
  for (const k of DELETE) if (k in mm) { delete mm[k]; d++ }
  fs.writeFileSync(file, JSON.stringify(dict, null, 2) + "\n")
  console.log(lang, "+" + a, "~" + o, "-" + d)
}
